actions.script:
def Z = com.zenith.Fmt.INSTANCE
// back link to the subscriptions list, on the current surface
try { def _u = ec.web?.getRequest()?.getRequestURI() ?: ''; def _sh = _u.startsWith('/qapps/') ? '/qapps' : '/apps'; context.backUrl = _sh + '/zenith/subscriptions' } catch (Exception _eb) { context.backUrl = '/apps/zenith/subscriptions' }

def statusDescMap = [SubActive:'Active', SubTrial:'Trial', SubPastDue:'Past Due', SubPaused:'Paused', SubCancelled:'Cancelled', SubExpired:'Expired']
def statusColorMap = [SubActive:['#059669','#ECFDF5'], SubTrial:['#D97706','#FFFBEB'], SubPastDue:['#DC2626','#FEF2F2'], SubPaused:['#6B7280','#F3F4F6'], SubCancelled:['#DC2626','#FEF2F2'], SubExpired:['#6B7280','#F3F4F6']]
def _st = sub?.statusId
context.subStatusLabel = statusDescMap[_st] ?: (_st ?: '')
def _sc = statusColorMap[_st] ?: ['#6B7280','#F3F4F6']
context.subStatusFg = _sc[0]; context.subStatusBg = _sc[1]

def _svg = { int sz, String paths -> '<svg width="' + sz + '" height="' + sz + '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">' + paths + '</svg>' }
// info-row icons (16px)
def icIdCard = _svg(16, '<path d="M16 10h2"/><path d="M16 14h2"/><path d="M6.17 15a3 3 0 0 1 5.66 0"/><circle cx="9" cy="11" r="2"/><rect x="2" y="5" width="20" height="14" rx="2"/>')
def icUsers = _svg(16, '<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><path d="M16 3.128a4 4 0 0 1 0 7.744"/><path d="M22 21v-2a4 4 0 0 0-3-3.87"/><circle cx="9" cy="7" r="4"/>')
def icClip = _svg(16, '<rect width="8" height="4" x="8" y="2" rx="1" ry="1"/><path d="M16 4h2a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h2"/>')
def icCheck = _svg(16, '<circle cx="12" cy="12" r="10"/><path d="m16 9-5.5 5.5L8 12"/>')
def icCal = _svg(16, '<path d="M8 2v3"/><path d="M16 2v3"/><rect x="3" y="3" width="18" height="18" rx="2"/><path d="M3 9h18"/>')
def icClock = _svg(16, '<circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/>')
def icMinus = _svg(16, '<circle cx="12" cy="12" r="10"/><path d="M8 12h8"/>')
def icZap = _svg(16, '<path d="M15.914 4a1.5 1.5 0 0 0-2.474-1.561l-9 9A1.5 1.5 0 0 0 5.5 14h4.002a.5.5 0 0 1 .471.666L8.086 20a1.5 1.5 0 0 0 2.475 1.56l9-9A1.5 1.5 0 0 0 18.5 10h-3.997a.5.5 0 0 1-.472-.667z"/>')
def icPct = _svg(16, '<line x1="19" x2="5" y1="5" y2="19"/><circle cx="6.5" cy="6.5" r="2.5"/><circle cx="17.5" cy="17.5" r="2.5"/>')
def icFile = _svg(16, '<path d="M6 22a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h8a2.4 2.4 0 0 1 1.704.706l3.588 3.588A2.4 2.4 0 0 1 20 8v12a2 2 0 0 1-2 2z"/><path d="M14 2v5a1 1 0 0 0 1 1h5"/><path d="M10 9H8"/><path d="M16 13H8"/><path d="M16 17H8"/>')

def _d = { d -> d ? ec.l10n.format(d, 'dd-MM-yyyy') : '&#8212;' }
def _money = { a -> '&#8377; ' + Z.inr(ec.l10n.format(a ?: 0, '#,##0.00')) }
def _esc = { s -> s == null ? '' : s.toString().replace('&','&amp;').replace('<','&lt;').replace('>','&gt;') }
def _row = { String ico, String label, String valHtml -> '<div class="es-info-row"><span class="es-info-ico">' + ico + '</span><span class="es-info-label">' + label + '</span><span class="es-info-val">' + valHtml + '</span></div>' }

def _planTxt = plan ? (_esc(plan.planName) + (plan.planCode ? (' (' + _esc(plan.planCode) + ')') : '')) : (_esc(sub?.planId) ?: '&#8212;')
def _statusPill = '<span class="es-info-pill" style="color:' + context.subStatusFg + ';background:' + context.subStatusBg + '">' + context.subStatusLabel + '</span>'
def _autoRenew = sub?.autoRenew == 'Y' ? 'Yes' : (sub?.autoRenew == 'N' ? 'No' : '&#8212;')
def _notes = sub?.notes ? _esc(sub.notes) : '&#8212;'
def _info = new StringBuilder()
_info.append(_row(icIdCard, 'Subscription ID', _esc(sub?.subscriptionNumber) ?: '&#8212;'))
_info.append(_row(icUsers, 'Customer', _esc(sub?.customerPartyId) ?: '&#8212;'))
_info.append(_row(icClip, 'Plan', _planTxt))
_info.append(_row(icCheck, 'Status', _statusPill))
_info.append(_row(icCal, 'Started on', _d(sub?.startDate)))
_info.append(_row(icCal, 'Ends on', _d(sub?.endDate)))
_info.append(_row(icClock, 'Trial ends on', _d(sub?.trialEndDate)))
_info.append(_row(icMinus, 'Next payment on', _d(sub?.nextBillingDate)))
_info.append(_row(icZap, 'Amount', _money(sub?.billingAmount)))
_info.append(_row(icPct, 'Tax (GST)', _money(sub?.gstAmount)))
_info.append(_row(icCheck, 'Auto renew', _autoRenew))
_info.append(_row(icFile, 'Notes', _notes))
context.infoHtml = _info.toString()

// action tiles (20px icons); each forwards its click to a hidden real Moqui trigger/submit
def tPause = _svg(20, '<rect x="14" y="3" width="5" height="18" rx="1"/><rect x="5" y="3" width="5" height="18" rx="1"/>')
def tRotate = _svg(20, '<path d="M21 12a9 9 0 1 1-9-9c2.52 0 4.93 1 6.74 2.74L21 8"/><path d="M21 3v5h-5"/>')
def tX = _svg(20, '<path d="M18 6 6 18"/><path d="m6 6 12 12"/>')
def tSwap = _svg(20, '<path d="M8 3 4 7l4 4"/><path d="M4 7h16"/><path d="m16 21 4-4-4-4"/><path d="M20 17H4"/>')
def tPlay = _svg(20, '<polygon points="6 3 20 12 6 21 6 3"/>')
def _tile = { String act, String cls, String ico, String label, String subl -> '<div class="es-tile ' + cls + '" data-act="' + act + '"><span class="es-tile-ico">' + ico + '</span><span class="es-tile-lbl">' + label + '</span><span class="es-tile-sub">' + subl + '</span></div>' }
def _tiles = new StringBuilder()
if (modCanWrite) {
    if (_st == 'SubTrial') _tiles.append(_tile('activate', 'es-tile-green', tRotate, 'Activate', 'Start now'))
    if (_st == 'SubActive') _tiles.append(_tile('pause', 'es-tile-primary', tPause, 'Pause', 'Stop for now'))
    if (_st == 'SubPaused') _tiles.append(_tile('resume', 'es-tile-green', tPlay, 'Resume', 'Start again'))
    if (_st == 'SubActive' || _st == 'SubPastDue') _tiles.append(_tile('renew', 'es-tile-green', tRotate, 'Renew', 'Keep going'))
    if (_st != 'SubCancelled' && _st != 'SubExpired') _tiles.append(_tile('cancel', 'es-tile-red', tX, 'Cancel', 'End this'))
    if (_st == 'SubActive' || _st == 'SubTrial') _tiles.append(_tile('change', 'es-tile-blue', tSwap, 'Change plan', 'Pick another plan'))
}
context.tilesHtml = _tiles.length() ? ('<div class="es-actions-grid">' + _tiles.toString() + '</div>') : '<div class="es-noact">No actions available for this subscription.</div>'

// activity rows
def _act = new StringBuilder()
(activities ?: []).take(6).each { a ->
    def _typeDesc = a.activityType
    try { def _e = ec.entity.find("moqui.basic.Enumeration").condition("enumId", a.activityType).useCache(true).one(); if (_e?.description) _typeDesc = _e.description } catch (Exception _ee) {}
    _act.append('<tr><td style="color:#6B7280">' + (a.activityDate ? ec.l10n.format(a.activityDate, 'dd-MM-yyyy HH:mm') : '&#8212;') + '</td><td style="color:#111827;font-weight:500">' + (_esc(_typeDesc) ?: '&#8212;') + '</td><td style="color:#6B7280">' + (_esc(a.description) ?: '&#8212;') + '</td></tr>')
}
context.activityHtml = _act.length() ? _act.toString() : '<tr><td colspan="3" style="color:#9CA3AF">No activity yet.</td></tr>'

// invoice rows
def _inv = new StringBuilder()
(invoices ?: []).take(6).each { iv ->
    def _sLbl = iv.statusId
    try { def _si = ec.entity.find("moqui.basic.StatusItem").condition("statusId", iv.statusId).useCache(true).one(); if (_si?.description) _sLbl = _si.description } catch (Exception _es2) {}
    def _low = (_sLbl ?: '').toString().toLowerCase()
    def _cls = 'es-badge-grey'
    if (_low.contains('paid') || _low.contains('received') || _low.contains('final')) _cls = 'es-badge-green'
    else if (_low.contains('cancel') || _low.contains('void')) _cls = 'es-badge-red'
    else if (_low.contains('sent') || _low.contains('process') || _low.contains('issued')) _cls = 'es-badge-blue'
    else if (_low.contains('overdue') || _low.contains('due')) _cls = 'es-badge-warn'
    _inv.append('<tr><td><span class="es-invlink">' + (_esc(iv.invoiceNumber) ?: _esc(iv.subscriptionInvoiceId)) + '</span></td><td>' + _d(iv.invoiceDate) + '</td><td>' + _d(iv.periodFrom) + '</td><td>' + _d(iv.periodTo) + '</td><td style="color:#111827">' + _money(iv.totalAmount) + '</td><td><span class="es-badge ' + _cls + '">' + _esc(_sLbl) + '</span></td></tr>')
}
context.invoiceHtml = _inv.length() ? _inv.toString() : '<tr><td colspan="6" style="color:#9CA3AF">No invoices yet.</td></tr>'
